@props([
    'name' => null,
    'size' => 'default',
    'flyout' => false,
    'flyoutPosition' => 'right',
    'dismissible' => true,
    'closable' => true,
    'alert' => false,
    'open' => false,
    'preview' => false,
])

@aware([
    'name' => null,
])

@php
    $isFlyout = (bool) $flyout;
    $position = in_array($flyoutPosition, ['right', 'left', 'bottom'], true) ? $flyoutPosition : 'right';

    $dialogClasses = collect([
        'dialog__content',
        'fixed z-50 border border-zinc-200 bg-white p-0 text-zinc-950 shadow-xl',
        'dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-50',
        'backdrop:bg-zinc-950/50 backdrop:backdrop-blur-[2px]',
        'motion-safe:transition-[opacity,transform] motion-safe:duration-200 motion-safe:ease-[cubic-bezier(0.16,1,0.3,1)]',
        'open:opacity-100 open:motion-safe:scale-100',
        'opacity-0 motion-safe:scale-[0.98]',
    ]);

    if ($isFlyout) {
        $dialogClasses->push('m-0 h-dvh max-h-dvh w-full max-w-md rounded-none');
        $dialogClasses->push(match ($position) {
            'left' => 'left-0 right-auto top-0 translate-x-0 translate-y-0',
            'bottom' => 'bottom-0 left-0 right-0 top-auto h-auto max-h-[85dvh] w-full max-w-none translate-x-0 translate-y-0 rounded-t-2xl',
            default => 'left-auto right-0 top-0 translate-x-0 translate-y-0',
        });
    } else {
        $dialogClasses->push('left-1/2 top-1/2 w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 rounded-xl');
        $dialogClasses->push($size === 'sm' ? 'max-w-sm' : 'max-w-lg');
    }

    $panelClasses = collect([
        'dialog__panel',
        'relative flex max-h-[min(85dvh,calc(100dvh-2rem))] flex-col p-6',
    ]);

    $closeButtonClasses = 'absolute right-4 top-4 inline-flex size-8 items-center justify-center rounded-md text-zinc-500 transition hover:bg-zinc-100 hover:text-zinc-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-50 dark:focus-visible:ring-zinc-300/20';

    $isPreview = (bool) $preview;
    $isOpen = (bool) $open;

    // Render the slot once so title/description can mint their own ids, then
    // wire aria-labelledby / aria-describedby from those ids (avoids @aware
    // blind spots when ids are generated inside the parent view).
    $slotHtml = $slot->toHtml();

    $titleId = null;
    $descriptionId = null;

    if (preg_match('/\sdata-dialog-title="([^"]+)"/', $slotHtml, $titleMatch) === 1) {
        $titleId = $titleMatch[1];
    }

    if (preg_match('/\sdata-dialog-description="([^"]+)"/', $slotHtml, $descriptionMatch) === 1) {
        $descriptionId = $descriptionMatch[1];
    }
@endphp

@if ($isPreview)
    @php
        $previewPanelClasses = collect([
            'dialog__content',
            'relative z-10 w-full rounded-xl border border-zinc-200 bg-white p-0 text-zinc-950 shadow-xl',
            'dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-50',
            $size === 'sm' ? 'max-w-sm' : 'max-w-lg',
        ])->implode(' ');
    @endphp

    <div {{
        $attributes->class([
            'dialog__preview',
            'relative flex min-h-[18rem] w-full items-center justify-center overflow-hidden rounded-xl border border-zinc-200 bg-zinc-100/60 p-6 dark:border-zinc-800 dark:bg-zinc-900/60',
        ])
    }}>
        <div
            class="pointer-events-none absolute inset-0 bg-zinc-950/50 backdrop-blur-[2px] dark:bg-zinc-950/60"
            aria-hidden="true"
        ></div>

        <div
            class="{{ $previewPanelClasses }}"
            role="{{ $alert ? 'alertdialog' : 'dialog' }}"
            aria-modal="true"
            @if (filled($titleId)) aria-labelledby="{{ $titleId }}" @endif
            @if (filled($descriptionId)) aria-describedby="{{ $descriptionId }}" @endif
            data-dialog-content
            data-dialog-preview
        >
            <div @class($panelClasses->all()) data-dialog-panel>
                @if ($closable)
                    <button
                        type="button"
                        class="{{ $closeButtonClasses }}"
                        data-dialog-close
                        tabindex="-1"
                        aria-hidden="true"
                        disabled
                    >
                        <x-ui::icon name="x" class="size-4" />
                    </button>
                @endif

                {!! $slotHtml !!}
            </div>
        </div>
    </div>
@else
    <dialog {{
        $attributes->class($dialogClasses->all())->merge([
            'data-dialog-content' => true,
            'data-dialog-dismissible' => $dismissible ? 'true' : 'false',
            'data-dialog-name' => filled($name) ? $name : null,
            'data-dialog-flyout' => $isFlyout ? 'true' : 'false',
            'aria-modal' => 'true',
            'aria-labelledby' => filled($titleId) ? $titleId : null,
            'aria-describedby' => filled($descriptionId) ? $descriptionId : null,
            'role' => $alert ? 'alertdialog' : 'dialog',
            'open' => $isOpen ? true : null,
        ])
    }}>
        <div @class($panelClasses->all()) data-dialog-panel>
            @if ($closable)
                <button
                    type="button"
                    class="{{ $closeButtonClasses }}"
                    data-dialog-close
                    aria-label="{{ __('stencil-ui::messages.dialog_close') }}"
                >
                    <x-ui::icon name="x" class="size-4" />
                </button>
            @endif

            {!! $slotHtml !!}
        </div>
    </dialog>
@endif

/**
 * Stencil — accessible modal dialogs (native <dialog>, vanilla JS).
 */

const DIALOG_CONTENT_SELECTOR = '[data-dialog-content]';
const initialized = new WeakSet();

/** @type {Map<string, HTMLDialogElement>} */
const namedDialogs = new Map();

/**
 * @param {ParentNode} root
 */
export function initDialogs(root = document) {
    root.querySelectorAll(DIALOG_CONTENT_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLDialogElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindDialog(element);
    });

    root.querySelectorAll('[data-dialog-trigger], [data-dialog-open]').forEach((trigger) => {
        if (!(trigger instanceof HTMLElement)) {
            return;
        }

        if (trigger.dataset.dialogTriggerBound === 'true') {
            return;
        }

        trigger.dataset.dialogTriggerBound = 'true';
        bindTrigger(trigger);
    });
}

/**
 * @param {string} name
 */
export function showDialog(name) {
    const dialog = namedDialogs.get(name);

    if (dialog instanceof HTMLDialogElement && !dialog.open) {
        openDialog(dialog);
    }
}

/**
 * @param {string} name
 */
export function closeDialog(name) {
    const dialog = namedDialogs.get(name);

    if (dialog instanceof HTMLDialogElement && dialog.open) {
        dialog.close();
    }
}

/**
 * @param {HTMLDialogElement} dialog
 */
function openDialog(dialog) {
    const previouslyFocused =
        document.activeElement instanceof HTMLElement ? document.activeElement : null;

    dialog.dataset.dialogPreviouslyFocused = previouslyFocused ? 'stored' : '';

    if (previouslyFocused) {
        dialog._stencilPreviousFocus = previouslyFocused;
    }

    if (typeof dialog.showModal === 'function') {
        dialog.showModal();
    } else {
        dialog.setAttribute('open', '');
    }

    dialog.dataset.state = 'open';
    dialog.dispatchEvent(
        new CustomEvent('stencil:dialog:open', {
            bubbles: true,
            detail: { name: dialog.dataset.dialogName ?? null },
        }),
    );

    focusInitialElement(dialog);
}

/**
 * @param {HTMLDialogElement} dialog
 */
function bindDialog(dialog) {
    const name = dialog.dataset.dialogName;

    if (typeof name === 'string' && name !== '') {
        namedDialogs.set(name, dialog);
    }

    const dismissible = dialog.dataset.dialogDismissible !== 'false';

    dialog.addEventListener('cancel', (event) => {
        if (!dismissible) {
            event.preventDefault();

            return;
        }

        dialog.dispatchEvent(
            new CustomEvent('stencil:dialog:cancel', {
                bubbles: true,
                detail: { name: name ?? null },
            }),
        );
    });

    dialog.addEventListener('close', () => {
        dialog.dataset.state = 'closed';
        restoreFocus(dialog);
        dialog.dispatchEvent(
            new CustomEvent('stencil:dialog:close', {
                bubbles: true,
                detail: { name: name ?? null },
            }),
        );
    });

    dialog.addEventListener('click', (event) => {
        if (!dismissible) {
            return;
        }

        const panel = dialog.querySelector('[data-dialog-panel]');

        if (!(panel instanceof HTMLElement)) {
            return;
        }

        if (event.target === dialog) {
            dialog.close();
        }
    });

    dialog.querySelectorAll('[data-dialog-close]').forEach((control) => {
        if (!(control instanceof HTMLElement)) {
            return;
        }

        control.addEventListener('click', (event) => {
            event.preventDefault();

            if (dialog.open) {
                dialog.close();
            }
        });
    });

    dialog.dataset.state = dialog.open ? 'open' : 'closed';
}

/**
 * @param {HTMLElement} trigger
 */
function bindTrigger(trigger) {
    trigger.addEventListener('click', (event) => {
        const target =
            event.target instanceof Element
                ? event.target.closest('button, a[href], [role="button"]')
                : null;

        if (target instanceof HTMLButtonElement && target.disabled) {
            return;
        }

        if (
            target instanceof HTMLAnchorElement &&
            target.getAttribute('aria-disabled') === 'true'
        ) {
            return;
        }

        event.preventDefault();

        const dialog = resolveDialogForTrigger(trigger);

        if (dialog instanceof HTMLDialogElement) {
            openDialog(dialog);
        }
    });
}

/**
 * @param {HTMLElement} trigger
 * @returns {HTMLDialogElement | null}
 */
function resolveDialogForTrigger(trigger) {
    const explicitName = trigger.dataset.dialogName ?? trigger.dataset.dialogOpen;

    if (typeof explicitName === 'string' && explicitName !== '') {
        const named = namedDialogs.get(explicitName);

        return named instanceof HTMLDialogElement ? named : null;
    }

    const root = trigger.closest('[data-dialog]');

    if (root instanceof HTMLElement) {
        const rootName = root.dataset.dialogName;

        if (typeof rootName === 'string' && rootName !== '') {
            const named = namedDialogs.get(rootName);

            if (named instanceof HTMLDialogElement) {
                return named;
            }
        }

        const local = root.querySelector(DIALOG_CONTENT_SELECTOR);

        if (local instanceof HTMLDialogElement) {
            return local;
        }
    }

    return null;
}

/**
 * @param {HTMLDialogElement} dialog
 */
function focusInitialElement(dialog) {
    const isAlert = dialog.getAttribute('role') === 'alertdialog';
    const focusTarget =
        dialog.querySelector('[data-dialog-initial-focus]') ??
        (isAlert ? dialog.querySelector('[data-dialog-cancel]') : null) ??
        dialog.querySelector(
            'button:not([data-dialog-close]):not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
        );

    if (focusTarget instanceof HTMLElement) {
        focusTarget.focus();
    }
}

/**
 * @param {HTMLDialogElement} dialog
 */
function restoreFocus(dialog) {
    const previous = dialog._stencilPreviousFocus;

    if (previous instanceof HTMLElement && document.contains(previous)) {
        previous.focus();
    }

    delete dialog._stencilPreviousFocus;
}

function closeAllDialogs() {
    document.querySelectorAll(DIALOG_CONTENT_SELECTOR).forEach((element) => {
        if (element instanceof HTMLDialogElement && element.open) {
            element.close();
        }
    });
}

if (typeof window !== 'undefined') {
    window.Stencil = window.Stencil ?? {};
    window.Stencil.dialog = (name) => ({
        show: () => showDialog(name),
        close: () => closeDialog(name),
    });
    window.Stencil.dialogs = {
        closeAll: () => closeAllDialogs(),
    };
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initDialogs(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initDialogs());
    } else {
        initDialogs();
    }
}
